const listBills = `-- name: ListBills :many
SELECT b.id, b.bill_type, b.bill_no, b.bill_date, b.status, b.cust_name, b.party_id, b.grand_total, b.balance_due,
       b.amount_paid, b.einv_status, b.source_bill_id, b.version, coalesce(ac.id, 0)::bigint AS account_copy_id,
       coalesce(u.full_name, '')::text AS created_by_name, count(*) OVER ()::bigint AS total
FROM bill b
LEFT JOIN app_user u ON u.id = b.created_by
LEFT JOIN LATERAL (SELECT c.id FROM bill c WHERE c.source_bill_id = b.id AND c.status <> 'cancelled'
                   ORDER BY c.id DESC LIMIT 1) ac ON true
WHERE ($1::bill_kind IS NULL OR b.bill_type = $1::bill_kind)
  AND ($2::doc_status IS NULL OR b.status = $2::doc_status)
  AND ($3::text IS NULL OR
       (CASE WHEN b.balance_due <= 0 THEN 'paid' WHEN b.amount_paid > 0 THEN 'partial' ELSE 'unpaid' END)
         = $3::text)
  AND ($4::einv_state IS NULL OR b.einv_status = $4::einv_state)
  AND ($5::bigint IS NULL OR b.party_id = $5::bigint)
  AND ($6::smallint IS NULL OR EXISTS (
        SELECT 1 FROM bill_line bl WHERE bl.bill_id = b.id AND bl.location_id = $6::smallint))
  AND ($7::date IS NULL OR b.bill_date >= $7::date)
  AND ($8::date IS NULL OR b.bill_date <= $8::date)
  AND ($9::text = '' OR b.bill_no ILIKE '%' || $9::text || '%' OR b.cust_name ILIKE '%' || $9::text || '%'
       OR b.cust_mobile ILIKE '%' || $9::text || '%')
  AND (NOT $10::bool OR (b.bill_type = 'account' AND b.source_bill_id IS NULL))
ORDER BY
  CASE WHEN $11::text = 'bill_date'   AND NOT $12::bool THEN b.bill_date END ASC,
  CASE WHEN $11::text = 'bill_date'   AND $12::bool     THEN b.bill_date END DESC,
  CASE WHEN $11::text = 'bill_no'     AND NOT $12::bool THEN b.bill_no END ASC,
  CASE WHEN $11::text = 'bill_no'     AND $12::bool     THEN b.bill_no END DESC,
  CASE WHEN $11::text = 'grand_total' AND NOT $12::bool THEN b.grand_total END ASC,
  CASE WHEN $11::text = 'grand_total' AND $12::bool     THEN b.grand_total END DESC,
  CASE WHEN $11::text = 'created_at'  AND NOT $12::bool THEN b.created_at END ASC,
  CASE WHEN $11::text = 'created_at'  AND $12::bool     THEN b.created_at END DESC,
  b.id DESC
LIMIT $14 OFFSET $13
`

type ListBillsParams struct {
	BillType      *BillKind  `json:"bill_type"`
	Status        *DocStatus `json:"status"`
	PaymentStatus *string    `json:"payment_status"`
	EinvStatus    *EinvState `json:"einv_status"`
	PartyID       *int64     `json:"party_id"`
	LocationID    *int16     `json:"location_id"`
	FromDate      *time.Time `json:"from_date"`
	ToDate        *time.Time `json:"to_date"`
	Q             string     `json:"q"`
	Unlinked      bool       `json:"unlinked"`
	Sort          string     `json:"sort"`
	Descending    bool       `json:"descending"`
	Off           int32      `json:"off"`
	Lim           int32      `json:"lim"`
}

type ListBillsRow struct {
	ID            int64            `json:"id"`
	BillType      BillKind         `json:"bill_type"`
	BillNo        *string          `json:"bill_no"`
	BillDate      time.Time        `json:"bill_date"`
	Status        DocStatus        `json:"status"`
	CustName      string           `json:"cust_name"`
	PartyID       *int64           `json:"party_id"`
	GrandTotal    decimal.Decimal  `json:"grand_total"`
	BalanceDue    *decimal.Decimal `json:"balance_due"`
	AmountPaid    decimal.Decimal  `json:"amount_paid"`
	EinvStatus    EinvState        `json:"einv_status"`
	SourceBillID  *int64           `json:"source_bill_id"`
	Version       int32            `json:"version"`
	AccountCopyID int64            `json:"account_copy_id"`
	CreatedByName string           `json:"created_by_name"`
	Total         int64            `json:"total"`
}

func (q *Queries) ListBills(ctx context.Context, arg ListBillsParams) ([]ListBillsRow, error) {
	rows, err := q.db.Query(ctx, listBills,
		arg.BillType,
		arg.Status,
		arg.PaymentStatus,
		arg.EinvStatus,
		arg.PartyID,
		arg.LocationID,
		arg.FromDate,
		arg.ToDate,
		arg.Q,
		arg.Unlinked,
		arg.Sort,
		arg.Descending,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListBillsRow{}
	for rows.Next() {
		var i ListBillsRow
		if err := rows.Scan(
			&i.ID,
			&i.BillType,
			&i.BillNo,
			&i.BillDate,
			&i.Status,
			&i.CustName,
			&i.PartyID,
			&i.GrandTotal,
			&i.BalanceDue,
			&i.AmountPaid,
			&i.EinvStatus,
			&i.SourceBillID,
			&i.Version,
			&i.AccountCopyID,
			&i.CreatedByName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

